type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Inbox",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const allowed = can(actor, "notification:read", {
    kind: "notification",
    orgId: org.id,
    recipientId: actor.userId,
  });
  if (!allowed) {
    notFound();
  }

  const pagination = searchParamsPaginationSchema.parse(search);
  const unreadOnly = search.filter === "unread";

  const page = await listNotifications(actor, {
    orgId: org.id,
    recipientId: actor.userId,
    unreadOnly,
    limit: pagination.perPage,
    cursor: pagination.cursor ?? null,
  });

  async function markRead(notificationId: NotificationId): Promise<void> {
    "use server";
    await markNotificationReadAction({ orgId: org.id, notificationId });
  }

  async function markAllRead(): Promise<void> {
    "use server";
    await markAllNotificationsReadAction({ orgId: org.id });
  }

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">Inbox</h1>
        <p className="mt-1 text-sm text-slate-600">
          {page.total} {unreadOnly ? "unread" : "total"} notifications
        </p>
      </header>

      <NotificationList
        notifications={page.items}
        onMarkRead={markRead}
        onMarkAllRead={markAllRead}
      />
    </div>
  );
}
/**
 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { eq, isNull } from "drizzle-orm";
import { shouldFilterArchived } from "@/lib/soft-delete";
import type { ArchiveScope, OrgId } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

const CURSOR_SEPARATOR = "|";

/**
 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
 * sort value alongside the id is what lets `listX` resume from a stable point
 * even when two rows share a timestamp.
 */
export function encodeCursor(id: string, sortValue: string): string {
  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
    "base64url",
  );
}

export function decodeCursor(
  cursor: string,
): { id: string; sortValue: string } | null {
  let decoded: string;
  try {
    decoded = Buffer.from(cursor, "base64url").toString("utf8");
  } catch {
    return null;
  }

  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;

  return {
    sortValue: decoded.slice(0, separatorAt),
    id: decoded.slice(separatorAt + 1),
  };
}

/**
 * The tenant predicate. Every repository read and write composes this — a
 * query that does not mention `org_id` is a cross-tenant leak waiting to
 * happen, so this is the only sanctioned way to express it.
 */
export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
  return eq(column, orgId);
}

/**
 * The soft-delete predicate, or `undefined` when the caller explicitly asked
 * for archived rows. The `includeArchived` decision itself lives in
 * `shouldFilterArchived()` so it cannot drift per repository.
 */
export function livePredicate(
  column: SQLiteColumn,
  scope: ArchiveScope,
): SQL | undefined {
  return shouldFilterArchived(scope) ? isNull(column) : undefined;
}
/**
 * Daily digest built by the digest job from a `DigestBundle`. Entries are
 * capped at `DIGEST_MAX_ENTRIES` so one noisy day cannot produce an
 * unbounded email.
 */
import { Link, Section, Text } from "@react-email/components";
import type { ReactElement } from "react";
import { DIGEST_MAX_ENTRIES } from "@/config/constants";
import { formatRelative } from "@/lib/date";
import type { DigestEntry } from "@/types/notification";
import { EmailButton } from "./_components/email-button";
import { EmailLayout } from "./_components/email-layout";

export type DigestEmailProps = {
  recipientName: string;
  orgName: string;
  entries: readonly DigestEntry[];
  inboxUrl: string;
};

const styles = {
  paragraph: { color: "#374151", fontSize: "15px", lineHeight: "24px" },
  entry: { borderTop: "1px solid #f3f4f6", padding: "10px 0" },
  entryTitle: { color: "#111827", fontSize: "14px", margin: 0 },
  entryMeta: { color: "#6b7280", fontSize: "12px", margin: "2px 0 0" },
  link: { color: "#6366f1", textDecoration: "none" },
  muted: { color: "#6b7280", fontSize: "13px", lineHeight: "20px" },
};

export function DigestEmail(props: DigestEmailProps): ReactElement | null {
  const { recipientName, orgName, entries, inboxUrl } = props;
  const shown = entries.slice(0, DIGEST_MAX_ENTRIES);
  const overflow = entries.length - shown.length;

  return (
    <EmailLayout
      preview={`${entries.length} update${entries.length === 1 ? "" : "s"} in ${orgName}`}
      heading={`Your ${orgName} digest`}
    >
      <Text style={styles.paragraph}>
        {recipientName}, here is what happened since your last digest.
      </Text>

      {shown.map((entry) => (
        <Section key={entry.notificationId} style={styles.entry}>
          <Text style={styles.entryTitle}>
            <Link href={entry.href} style={styles.link}>
              {entry.title}
            </Link>
          </Text>
          <Text style={styles.entryMeta}>
            {entry.kind.replace(/_/g, " ")} · {formatRelative(entry.occurredAt)}
          </Text>
        </Section>
      ))}

      {overflow > 0 ? (
        <Text style={styles.muted}>
          {`…and ${overflow} more update${overflow === 1 ? "" : "s"}.`}
        </Text>
      ) : null}

      <EmailButton href={inboxUrl} label="Open your inbox" />
    </EmailLayout>
  );
}
/**
 * Renders react-email templates and 'sends' them by writing the draft to the log. No network egress.
 */
import { createLogger } from "@/lib/logger";

export type OutgoingEmail = {
  to: string;
  subject: string;
  html: string;
  text: string;
};

export type RenderedEmail = { subject: string; html: string; text: string };

export type EmailTemplate =
  | "invite"
  | "digest"
  | "mention"
  | "invoice"
  | "welcome"
  | "password-reset"
  | "overdue";

const logger = createLogger("email-service");

/** Subject lines per template; the props fill in the bracketed parts. */
const SUBJECTS: Readonly<Record<EmailTemplate, string>> = {
  invite: "You have been invited to a Taskflow workspace",
  digest: "Your Taskflow digest",
  mention: "You were mentioned in Taskflow",
  invoice: "Your Taskflow invoice",
  welcome: "Welcome to Taskflow",
  "password-reset": "Reset your Taskflow password",
  overdue: "You have overdue issues",
};

/**
 * "Sends" a message. Taskflow has no outbound mail transport by design — the
 * corpus must build and run offline — so delivery means writing the draft to
 * the structured log, where the dev tools tab surfaces it.
 */
export async function sendEmail(message: OutgoingEmail): Promise<void> {
  logger.info("email.sent", {
    to: message.to,
    subject: message.subject,
    bytes: message.html.length,
  });
}

/**
 * Renders a template to both an HTML and a plain-text body. The text half is
 * derived from the HTML rather than written twice, so the two can never drift.
 */
export async function renderEmail(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): Promise<RenderedEmail> {
  const subject = subjectFor(template, props);
  const html = renderBody(template, props);

  return { subject, html, text: toPlainText(html) };
}

function subjectFor(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const base = SUBJECTS[template];
  const orgName = props.orgName;
  return typeof orgName === "string" ? `${base} — ${orgName}` : base;
}

function renderBody(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const rows = Object.entries(props)
    .filter(([, value]) => value !== null && value !== undefined)
    .map(
      ([key, value]) =>
        `<tr><td>${escapeHtml(key)}</td><td>${escapeHtml(String(value))}</td></tr>`,
    )
    .join("");

  return [
    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
    `<table>${rows}</table>`,
    "</body></html>",
  ].join("");
}

function toPlainText(html: string): string {
  return html
    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
