            </Link>

            {notification.readAt === null ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onMarkRead(notification.id)}
              >
                Mark read
              </Button>
            ) : null}
          </li>
        ))}
      </ul>
    </section>
  );
}
