import assert from 'node:assert/strict';
import { createTenant, issueInput, useTemporaryDatabase } from './tests/server/_support/fixtures';
import * as notifications from './src/server/services/notification-service';
import * as repo from './src/server/repositories/notification-repository';
import * as preferences from './src/server/repositories/notification-preference-repository';
import * as issues from './src/server/services/issue-service';
import * as projects from './src/server/services/project-service';
import * as invitations from './src/server/services/invitation-service';
import * as attachments from './src/server/services/attachment-service';
import * as webhooks from './src/server/services/webhook-service';
import * as usageRepo from './src/server/repositories/usage-repository';
import * as usage from './src/server/services/usage-service';
import * as search from './src/server/services/search-service';
import * as comments from './src/server/services/comment-service';
import { buildDigest, renderDigest } from './src/server/services/digest-service';
import * as userRepo from './src/server/repositories/user-repository';
import { emit, onHandlerError } from './src/lib/event-bus';
import { toIsoTimestamp } from './src/types/common';
import type { MemberId } from './src/types/common';
const cleanup = await useTemporaryDatabase();
const errors: unknown[] = [];
onHandlerError((_, error) => errors.push(error));
try {
  const t = await createTenant('alert-smoke');
  const list = (actor = t.actors.admin, cursor: string | null = null, limit = 100) => notifications.listNotifications(actor, {orgId:t.org.id,recipientId:actor.userId,unreadOnly:false,cursor,limit});
  const i = await issues.createIssue(t.actors.member, issueInput(t.org.id,t.project.id,{assigneeId:t.userIds.admin}));
  const href = "'`/${t.org.slug}/projects/${t.project.slug}/issues/${i.number}`;
  let page = await list();
  assert.equal(page.items.length,1);
  assert.equal(page.items[0].href,href);
  await assert.rejects(notifications.listNotifications(t.actors.owner,{orgId:t.org.id,recipientId:t.userIds.admin,unreadOnly:false,limit:25}));
  await assert.rejects(notifications.markRead(t.actors.owner,{orgId:t.org.id,notificationId:page.items[0].id}));
  await assert.rejects(notifications.updatePreference(t.actors.owner,{orgId:t.org.id,userId:t.userIds.admin,kind:'"'issue_assigned',inApp:false,email:true,digestOnly:false}));
  await issues.moveIssue(t.actors.member,{orgId:t.org.id,issueId:i.id,toStatus:'in_progress',toIndex:0});
  assert.equal((await list()).items.filter(n=>n.kind==='issue_status_changed').length,1);
  await issues.changeIssueStatus(t.actors.admin,{orgId:t.org.id,issueId:i.id,status:'done'});
  assert.equal((await list()).items.filter(n=>n.kind==='issue_status_changed').length,1);
  await emit('member.joined',{orgId:t.org.id,actorId:t.userIds.member,occurredAt:toIsoTimestamp(new Date()),userId:t.userIds.member,memberId:'new-member' as MemberId,role:'member'});
  assert.equal((await list(t.actors.owner)).items[0].href,"'`/${t.org.slug}/settings/members`);
  assert.equal((await list(t.actors.member)).total,0);
  const otherUnread = await repo.countUnread(t.org.id,t.userIds.owner);
  await notifications.markAllRead(t.actors.admin,t.org.id);
  assert.equal(await repo.countUnread(t.org.id,t.userIds.admin),0);
  assert.equal(await repo.countUnread(t.org.id,t.userIds.owner),otherUnread);
  await preferences.upsertPreference({orgId:t.org.id,userId:t.userIds.admin,kind:'"'issue_overdue',inApp:false,email:true,digestOnly:true});
  for(let j=0;j<175;j++) await notifications.notify(t.org.id,j%2?'issue_overdue':'comment_mention',[t.userIds.admin],{title:"'`Row ${j}`,body:'"'Body',href,actorId:null});
  const ids = new Set<string>();
  let cursor: string | null = null;
  let expected = 0;
  do {
    page = await list(t.actors.admin,cursor,7);
    expected = page.total;
    for(const n of page.items) {assert("'!ids.has(n.id));assert(n.channels.includes('"'in_app'));ids.add(n.id);}
    cursor = page.nextCursor;
  } while(cursor);
  assert.equal(ids.size,expected);
  const bundle = await buildDigest(t.org.id,t.userIds.admin,toIsoTimestamp(new Date(Date.now()-86400000)),toIsoTimestamp(new Date()));
  assert(bundle);
  assert(bundle.entries.every(e=>e.href===href));
  const user = await userRepo.findUserById(t.userIds.admin);
  assert(user);
  assert((await renderDigest(bundle,user)).html.includes("'`href="${href}"`));
  const detach = search.registerSearchListeners();
  await search.indexIssue(t.org.id,i);
  await search.indexProject(t.org.id,t.project);
  const comment = await comments.createComment(t.actors.member,{orgId:t.org.id,issueId:i.id,body:'"'smoke comment marker',parentId:null,mentionedUserIds:[]});
  for(const [q,kind,path] of [[i.title,'issue',href],['smoke comment marker','comment',href],[t.project.name,'project',"'`/${t.org.slug}/projects/${t.project.slug}`]] as const) {
    const hits = await search.search(t.actors.member,{orgId:t.org.id,q,kinds:[kind],limit:25,cursor:null});
    assert.equal(hits.items[0].href,path);
  }
  detach();
  const f = await createTenant('"'alert-quota','free');
  const ownerAlerts = () => notifications.listNotifications(f.actors.owner,{orgId:f.org.id,recipientId:f.userIds.owner,kind:['plan_limit_reached'],unreadOnly:true,limit:100});
  await projects.createProject(f.actors.member,{orgId:f.org.id,name:'Second project',key:'SEC',description:null,visibility:'org',leadId:null,color:'#6366f1',targetDate:null});
  const refuseProject = () => projects.createProject(f.actors.member,{orgId:f.org.id,name:'Third project',key:'THI',description:null,visibility:'org',leadId:null,color:'#6366f1',targetDate:null});
  await Promise.all(Array.from({length:4},()=>assert.rejects(refuseProject())));
  assert.equal((await ownerAlerts()).total,1);
  await notifications.markRead(f.actors.owner,{orgId:f.org.id,notificationId:(await ownerAlerts()).items[0].id});
  await assert.rejects(refuseProject());
  assert.equal((await ownerAlerts()).total,1);
  await assert.rejects(invitations.inviteMember(f.actors.admin,{orgId:f.org.id,email:'new@smoke.test',role:'member'}));
  const fi = await issues.createIssue(f.actors.member,issueInput(f.org.id,f.project.id));
  await usageRepo.incrementUsage(f.org.id,{storageMbUsed:100});
  await assert.rejects(attachments.addAttachment(f.actors.member,{orgId:f.org.id,issueId:fi.id,fileName:'file',mimeType:'text/plain',sizeBytes:1,storageKey:'file'}));
  await assert.rejects(webhooks.createWebhook(f.actors.admin,{orgId:f.org.id,url:'https://example.com/hook',description:null,eventTypes:['issue.created']}));
  for(let j=1;j<100;j++) await issues.createIssue(f.actors.member,issueInput(f.org.id,f.project.id));
  await assert.rejects(issues.createIssue(f.actors.member,issueInput(f.org.id,f.project.id)));
  assert.equal((await ownerAlerts()).total,5);
  await usage.recomputeUsage(f.org.id);
  assert.equal((await ownerAlerts()).total,5);
  assert.deepEqual(errors,[]);
  console.log('Alert behavior checks passed');
} finally { cleanup(); }
EOF
